mapper.select:
SELECT r.register_id, r.team_id, r.team_name, r.team_members, r.work_name, r.teacher_name, r.work_description, r.register_time, ROUND(COALESCE(AVG(s.score), 0), 2) as avg_score FROM competition_register r INNER JOIN ( SELECT competition_id, team_id, COALESCE( MIN(CASE WHEN register_id = team_id THEN register_id END), MIN(register_id) ) AS main_register_id FROM competition_register WHERE competition_id = #{competitionId} AND team_id IS NOT NULL GROUP BY competition_id, team_id ) team_main ON team_main.main_register_id = r.register_id LEFT JOIN competition_score s ON r.register_id = s.participation_id WHERE r.competition_id = #{competitionId} AND r.team_id IS NOT NULL GROUP BY r.register_id, r.team_id, r.team_name, r.team_members, r.work_name, r.teacher_name, r.work_description, r.register_time HAVING 1=1
AND COALESCE(AVG(s.score), 0) >= #{minScore}
AND COALESCE(AVG(s.score), 0) <= #{maxScore}
ORDER BY
COALESCE(AVG(s.score), 0) DESC COALESCE(AVG(s.score), 0) ASC r.register_time DESC, r.register_id DESC

mapper.update:
update competition
competition_name = #{competitionName}, description = #{description}, competition_type = #{competitionType}, competition_link = #{competitionLink}, banner_image = #{bannerImage}, announcement = #{announcement}, learning_link = #{learningLink}, learning_image = #{learningImage}, learning_description = #{learningDescription}, learning_count = #{learningCount}, register_start_time = #{registerStartTime}, register_end_time = #{registerEndTime}, update_time = sysdate()
where competition_id = #{competitionId}
